```python
def next_field(line, start):
    if line[start] != '"':
        end = line.find(',', start)
        if end == -1:
            end = len(line)
        field = line[start:end]
        return (field, end + 1)

    quote_end = line.find('"', start + 1)
    while quote_end != -1:
        doubled_quote_pos = line.find('""', start, quote_end)
        if doubled_quote_pos == -1:
            break
        line = line[:doubled_quote_pos] + line[doubled_quote_pos + 1:]
        quote_end -= 1
        doubled_quote_pos = line.find('""', start, quote_end)

    end = line.find(',', start + 1)
    if end == -1:
        end = len(line)

    field = line[start + 1:end].replace('""', '"')
    return (field, end + 1)
